package com.primehr.security;
import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class LdParticipationPermissionGuardTest{
 @Test void nominationAllowsOwnScopeWhileDeliveryFinalizationRequiresAgencyScope(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);LdParticipationPermissionGuard guard=new LdParticipationPermissionGuard(client);when(client.resolve(LdParticipationPermissionGuard.NOMINATION,"token")).thenReturn(permission(true,true,true,true,true,false,PermissionDataScope.OWN_RECORDS));when(client.resolve(LdParticipationPermissionGuard.DELIVERY,"token")).thenReturn(permission(true,false,true,false,false,true,PermissionDataScope.AGENCY_WIDE));assertThat(guard.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.SUBMIT,"token")).isEqualTo(PermissionDataScope.OWN_RECORDS);assertThat(guard.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.FINALIZE,"token")).isEqualTo(PermissionDataScope.AGENCY_WIDE);}
 @Test void deliveryOwnScopeAndMissingActionFailClosed(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(true,false,false,false,false,false,PermissionDataScope.OWN_RECORDS));LdParticipationPermissionGuard guard=new LdParticipationPermissionGuard(client);assertThatThrownBy(()->guard.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.ACCESS,"token")).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->guard.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.APPROVE,"token")).isInstanceOf(AccessDeniedException.class);}
 private EffectiveFeaturePermission permission(boolean access,boolean add,boolean edit,boolean submit,boolean approve,boolean finalize,PermissionDataScope scope){return new EffectiveFeaturePermission("feature",false,access,add,edit,false,false,submit,approve,false,false,finalize,scope);}
}
